def _install_updated_at_triggers() -> None:
    updated_at_tables = (
        ("core", "tenants"),
        ("core", "users"),
        ("core", "user_profiles"),
        ("core", "user_preferences"),
        ("core", "feature_flags"),
        ("graph", "entities"),
        ("graph", "entity_relationships"),
        ("memory", "memory_items"),
        ("integrations", "integrations"),
        ("integrations", "oauth_credentials"),
        ("integrations", "sync_cursors"),
        ("integrations", "webhook_subscriptions"),
        ("agent", "conversations"),
        ("agent", "agent_runs"),
        ("agent", "tool_executions"),
        ("agent", "approvals"),
        ("work", "projects"),
        ("work", "goals"),
        ("work", "tasks"),
        ("crm", "contacts"),
        ("proactive", "insights"),
        ("proactive", "notifications"),
    )
    for schema, table in updated_at_tables:
        op.execute(
            f"""
            CREATE TRIGGER trg_{table}_updated_at
            BEFORE UPDATE ON {schema}.{table}
            FOR EACH ROW EXECUTE FUNCTION core.set_updated_at()
            """
        )


def _install_row_level_security() -> None:
    # ``core.tenants`` has no tenant_id column: the row *is* the tenant.
    op.execute("ALTER TABLE core.tenants ENABLE ROW LEVEL SECURITY")
    op.execute("ALTER TABLE core.tenants FORCE ROW LEVEL SECURITY")
    op.execute(
        """
        CREATE POLICY tenant_isolation ON core.tenants
        USING (id = current_setting('app.tenant_id', true)::uuid)
        WITH CHECK (id = current_setting('app.tenant_id', true)::uuid)
        """
    )

    for schema, table in TENANT_TABLES:
        target = f"{schema}.{table}"
        op.execute(f"ALTER TABLE {target} ENABLE ROW LEVEL SECURITY")
        op.execute(f"ALTER TABLE {target} FORCE ROW LEVEL SECURITY")
        op.execute(
            f"""
            CREATE POLICY tenant_isolation ON {target}
            USING (tenant_id = current_setting('app.tenant_id', true)::uuid)
            WITH CHECK (tenant_id = current_setting('app.tenant_id', true)::uuid)
            """
        )

    for schema, table in USER_TABLES:
        target = f"{schema}.{table}"
        op.execute(
            f"""
            CREATE POLICY user_isolation ON {target}
            USING (
                current_setting('app.role', true) = 'service'
                OR user_id = current_setting('app.user_id', true)::uuid
            )
            WITH CHECK (
                current_setting('app.role', true) = 'service'
                OR user_id = current_setting('app.user_id', true)::uuid
            )
            """
        )


def _install_roles_and_grants() -> None:
    # Role attributes are deliberately minimal. ``zara_provisioner`` is the only
    # role allowed to look up/create identity rows before a tenant context exists;
    # it is internal to the first-request provisioning path.
    for role, extra in (
        ("zara_app", "NOLOGIN"),
        ("zara_audit_writer", "NOLOGIN"),
        ("zara_readonly", "NOLOGIN"),
        ("zara_provisioner", "NOLOGIN BYPASSRLS"),
    ):
        op.execute(
            f"""
            DO $$
            BEGIN
                IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = '{role}') THEN
                    CREATE ROLE {role} {extra};
                END IF;
            END
            $$
            """
        )

    op.execute("GRANT zara_app, zara_audit_writer, zara_provisioner, zara_readonly TO CURRENT_USER")
    op.execute("GRANT zara_audit_writer, zara_provisioner TO zara_app")
    op.execute("GRANT zara_readonly TO zara_audit_writer")

    op.execute(
        "GRANT USAGE ON SCHEMA core, graph, memory, integrations, agent, work, crm, proactive, audit"
        " TO zara_app, zara_provisioner, zara_readonly"
    )
    op.execute("GRANT USAGE ON SCHEMA audit TO zara_audit_writer")

    for schema in ("core", "graph", "memory", "integrations", "agent", "work", "crm", "proactive"):
        op.execute(
            f"GRANT SELECT, INSERT, UPDATE, DELETE ON ALL TABLES IN SCHEMA {schema} TO zara_app"
        )
        op.execute(f"GRANT SELECT ON ALL TABLES IN SCHEMA {schema} TO zara_readonly")
        op.execute(
            f"ALTER DEFAULT PRIVILEGES IN SCHEMA {schema} "
            f"GRANT SELECT, INSERT, UPDATE, DELETE ON TABLES TO zara_app"
        )
    op.execute("GRANT SELECT ON ALL TABLES IN SCHEMA core TO zara_provisioner")
    op.execute(
        "GRANT INSERT, UPDATE ON core.tenants, core.users, core.user_profiles TO zara_provisioner"
    )
    # Session-token resolution happens before a tenant context exists, so the
    # provisioner records ``last_used_at`` on the session row it just matched.
    op.execute("GRANT UPDATE ON core.auth_sessions TO zara_provisioner")
    op.execute("GRANT USAGE, SELECT ON ALL SEQUENCES IN SCHEMA agent TO zara_app")
    op.execute("GRANT USAGE, SELECT ON ALL SEQUENCES IN SCHEMA core TO zara_app")

    # Audit is append-only: the API may read its tenant's trail, while writes go
    # through the narrow writer role. No role receives UPDATE or DELETE.
    op.execute("GRANT SELECT ON audit.audit_log TO zara_app")
    op.execute("GRANT SELECT ON audit.audit_log TO zara_readonly")
    op.execute("GRANT INSERT ON audit.audit_log TO zara_audit_writer")


def _install_audit_guards() -> None:
    op.execute(
        """
        CREATE OR REPLACE FUNCTION audit.reject_mutation()
        RETURNS trigger
        LANGUAGE plpgsql
        AS $$
        BEGIN
            RAISE EXCEPTION 'audit.audit_log is append-only';
        END;
        $$;
        """
    )
    op.execute(
        """
        CREATE TRIGGER trg_audit_log_append_only
        BEFORE UPDATE OR DELETE ON audit.audit_log
        FOR EACH ROW EXECUTE FUNCTION audit.reject_mutation()
        """
    )


